polymorph_files = glob.glob(f'{base_dir}/*_polymorphs.json')

for file_path in polymorph_files:
    if 'TiO2' in file_path:
        continue
    composition = file_path.split('/')[-1].replace('_polymorphs.json', '')
    try:
        with open(file_path, 'r') as f:
            comp_data = json.load(f)
            for item in comp_data:
                item['source_composition'] = composition
            consolidated.extend(comp_data)
    except:
        pass

